BEGIN;
CREATE TABLE module_audit_runs(id TEXT PRIMARY KEY,module_id TEXT NOT NULL CHECK(module_id IN ('udc-ldc','combined-prelims')),source_file TEXT NOT NULL,source_sha256 TEXT NOT NULL,crosswalk_file TEXT NOT NULL,crosswalk_sha256 TEXT NOT NULL,bank_sha256 TEXT NOT NULL,manifest_sha256 TEXT NOT NULL,policy TEXT NOT NULL,module_url TEXT NOT NULL,counts JSONB NOT NULL,imported_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX module_audit_runs_latest ON module_audit_runs(module_id,created_at DESC,id);
CREATE TABLE module_audit_items(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES module_audit_runs(id),legacy_id TEXT NOT NULL,paper_id TEXT NOT NULL,match_status TEXT NOT NULL CHECK(match_status IN ('exact_unique','ambiguous_exact','unmatched')),comparison TEXT NOT NULL CHECK(comparison IN ('agree','conflict','module_only','bank_only','neither','ambiguous','unmatched')),legacy JSONB NOT NULL,previous_report JSONB NOT NULL,reviewed_packets JSONB NOT NULL DEFAULT '[]',UNIQUE(run_id,legacy_id));
CREATE INDEX module_audit_items_filter ON module_audit_items(run_id,match_status,comparison,id);
CREATE INDEX module_audit_items_paper ON module_audit_items(run_id,paper_id,id);
CREATE TABLE module_audit_candidates(item_id TEXT NOT NULL REFERENCES module_audit_items(id),appearance_id TEXT NOT NULL,canonical_id TEXT NOT NULL,imported JSONB NOT NULL,PRIMARY KEY(item_id,appearance_id));
CREATE INDEX module_audit_candidates_canonical ON module_audit_candidates(canonical_id,item_id);
CREATE TABLE module_audit_triage(item_id TEXT PRIMARY KEY REFERENCES module_audit_items(id),state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','linked','dismissed')),version INTEGER NOT NULL DEFAULT 1,reason TEXT NOT NULL DEFAULT '',updated_by TEXT,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX module_audit_triage_state ON module_audit_triage(state,item_id);
CREATE TABLE module_audit_links(item_id TEXT NOT NULL REFERENCES module_audit_items(id),contribution_id TEXT NOT NULL REFERENCES bank_contributions(id),actor_id TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(item_id,contribution_id));
CREATE TABLE module_audit_events(id BIGSERIAL PRIMARY KEY,item_id TEXT NOT NULL REFERENCES module_audit_items(id),actor_id TEXT NOT NULL,action TEXT NOT NULL,detail JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX module_audit_events_target ON module_audit_events(item_id,id DESC);
CREATE TRIGGER module_audit_runs_immutable BEFORE UPDATE OR DELETE ON module_audit_runs FOR EACH ROW EXECUTE FUNCTION review_immutable();
CREATE TRIGGER module_audit_items_immutable BEFORE UPDATE OR DELETE ON module_audit_items FOR EACH ROW EXECUTE FUNCTION review_immutable();
CREATE TRIGGER module_audit_candidates_immutable BEFORE UPDATE OR DELETE ON module_audit_candidates FOR EACH ROW EXECUTE FUNCTION review_immutable();
CREATE TRIGGER module_audit_links_immutable BEFORE UPDATE OR DELETE ON module_audit_links FOR EACH ROW EXECUTE FUNCTION review_immutable();
CREATE TRIGGER module_audit_events_immutable BEFORE UPDATE OR DELETE ON module_audit_events FOR EACH ROW EXECUTE FUNCTION review_immutable();
GRANT SELECT,INSERT ON module_audit_runs,module_audit_items,module_audit_candidates,module_audit_links,module_audit_events TO mpsc;
GRANT SELECT,INSERT,UPDATE ON module_audit_triage TO mpsc;
GRANT USAGE,SELECT ON SEQUENCE module_audit_events_id_seq TO mpsc;
COMMIT;
